"use strict";const utils=require("../utils");module.exports=(defaultFuncs,api,ctx)=>async function deleteMessage(messageID,callback){let resolveFunc=()=>{};let rejectFunc=()=>{};const returnPromise=new Promise((resolve,reject)=>{resolveFunc=resolve;rejectFunc=reject});if(!callback){callback=(err,result)=>{if(err)return rejectFunc(err);resolveFunc(result)}}else{const _userCb=callback;callback=(err,result)=>{if(err){_userCb(err);return rejectFunc(err)}_userCb(null,result);resolveFunc(result)}}try{const form={};if(Array.isArray(messageID)){if(messageID.length===0)throw new Error("messageID array must not be empty");messageID.forEach((id,i)=>{form[`message_ids[${i}]`]=id})}else{form.message_id=messageID}const res=await defaultFuncs.post("https://www.facebook.com/ajax/mercury/delete_messages.php",ctx.jar,form).then(utils.parseAndCheckLogin(ctx,defaultFuncs));if(res&&res.error){throw new Error(String(res.error_msg||res.error||"deleteMessage failed"))}callback(null,{success:true})}catch(err){utils.error("deleteMessage",err);callback(err instanceof Error?err:new Error(String(err&&err.message?err.message:err)))}return returnPromise};
